:root {
  --background: #0A0F1E;
  --surface: #121A2B;
  --primary: #38BDF8;
  --secondary: #A855F7;
  --text: #F8FAFC;
  --muted: #94A3B8;
  --border: #26344D;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background-color: var(--background);
  color: var(--text);
  font-family: Arial, sans-serif;
}

.header {
  background-color: var(--surface);
  padding: 28px 20px;
  border-bottom: 1px solid var(--border);
}

.header h1 {
  color: var(--primary);
  margin: 0 0 8px;
}

.header p {
  color: var(--muted);
  margin: 0;
}

.dashboard {
  padding: 20px;
}

.card {
  background-color: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 22px;
  margin-bottom: 16px;
}

.card h2 {
  color: var(--text);
}

.card p {
  color: var(--muted);
}

button {
  background-color: var(--primary);
  color: #07111F;
  border: 1px solid var(--primary);
  border-radius: 10px;
  padding: 10px 18px;
  font-weight: bold;
}

